custom_css:
/* --- 像素小清新 by 蛋蛋没蛋蛋/喵呜小团 --- 
   🚫二传商用*/



/* =========================================
   🥚 全局字体
   ========================================= */
@import url("https://fontsapi.zeoseven.com/570/main/result.css"); /* Fusion Pixel */
@import url("https://fontsapi.zeoseven.com/65/main/result.css"); /* BoutiqueBitmap */
@import url("https://fontsapi.zeoseven.com/360/main/result.css");

body {
    font-family: "Fusion Pixel 12px M latin", "BoutiqueBitmap9x9", "ChillBitmap 7px", sans-serif;
    line-height: 2;
    font-weight: normal;
}


/* =========================================
   🥚 全局顏色
   ========================================= */
:root {
  --title-color: #986C44;    
  --darkword-color:  #7B5838;
  --woodboard-color: #f3dfb1; 
  --emword: #bfa488;
  --woodshadow: #D4A373;
  --woodlight: #FFEDC7;
}


/* =========================================
   🥚 全局隐藏 Webkit 系浏览器的滚动条
   ========================================= */
::-webkit-scrollbar {
  display: none;
}



/* =========================================
   🥚 下拉框/textarea
   ========================================= */
.select2-container--default .select2-selection--single, textarea, 
.text_pole, select, .select2-selection, select2-selection--multiple { 
    border-radius: 6px;
    background: #E1C9A5 !important;
    color: var(--darkword-color) !important;
	line-height: 1.5;
    padding: 2px 2px 2px 10px;
    font-family: "Fusion Pixel 12px M latin";
}



/* =========================================
   🥚 消除阴影
   ========================================= */
/*消除操作/编辑按钮阴影*/
.mes_button, .extraMesButtons>div, .mes_edit_buttons, .menu_button {
  filter: none !important;
}

/*消除正文编辑背景阴影*/
.reasoning_edit_textarea, .edit_textarea {
  background-color: transparent;
}

/*消除导航栏下方阴影*/
#top-bar {
  box-shadow: none !important;
}



/* =========================================
   🥚 消息渐变背景
   ========================================= */
.mes {
  padding: 0px;
  overflow: visible;
  background: #fffeec;
  background: linear-gradient(
        to bottom,
        rgba(255, 255, 255, 0.0) 0%,
        rgba(255, 255, 255, 0.8) 10%,
        rgba(255, 255, 255, 0.8) 60%,
        rgba(255, 255, 255, 1) 100%    /* 底部更白 */
    );
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
  border-radius: 12px;
}


/* 計次和剪頭平排 */
.flex-container.swipeRightBlock {
    flex-flow: row-reverse !important;              /* 改成水平排列 */
    align-items: center !important;         /* 垂直置中對齊 */
    justify-content: flex-end !important;   /* 整體靠右（可改成 flex-start 靠左） */
    gap: 0px !important;                    /* 箭頭與計數器之間的間距 */
    position: absolute; 
    right: 0;
    bottom: 0;
    pointer-events: auto;                   /* 確保可點擊（原本是 none） */
    padding: 8px;                        
}


.swipe_left {
    bottom: 5px !important;
}

.mes_button, .extraMesButtons > div, .mes_edit_buttons, .menu_button  {
background:none !important;
}


/* =========================================
   🥚 头像布局
   ========================================= */
/*头像背景*/
.mes {
    flex-direction: column;
    width: 100%;
    margin: 10px auto; 
    padding: 0px 0px;
    position: relative !important;
}

/* 头像图片 */
.mes .avatar {
    border: none !important;
    box-shadow: none !important;
    overflow: hidden !important;
    z-index: 20 !important;
}
.mes .avatar img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    z-index: 20 !important;
}

/* 父容器：作为画板，但不直接放背景图 */
.mesAvatarWrapper {
  display: flex;
  position: relative;
  width: 100%;
  aspect-ratio: 6.2 / 4;
  overflow: visible;
}

/* 2. “相框”层 */
.mesAvatarWrapper::after {
  content: "";
  position: absolute;
  top: 0%;
  left: 0;
  width: 100%;
  height: 100%;

  /* 背景图 */
  background-image: url("https://files.catbox.moe/jioz6h.gif");
  background-size: cover;
  background-position: center;
  z-index: 50 !important;
  pointer-events: none; /* 让鼠标可以穿透框点到下面的东西，如果需要的话 */
}

/* 3. 子元素（头像）：显示在框的下面 */
.mesAvatarWrapper .avatar {
    position: absolute;
    left: 15%;
    top: 22%;
    transform: translate(-50%, -50%);
    width: 11%;
    height: auto;
    z-index: 10 !important;
}



/* =========================================
   🥚 token,楼层,计时
   ========================================= */
.mes .tokenCounterDisplay, .mes .mesIDDisplay, .mes .mes_timer {
    display: block !important; /* 确保它显示出来 */
    position: absolute !important; 
    transform: translate(0,-50%);
    z-index: 60 !important;
    color: white !important; 
    text-align: left; /* 文字向右对齐 */
    font-weight: bold;
    pointer-events: none; /* 让鼠标穿透名字，防止挡住点击 */
    font-size: 1.4vh;
    opacity:1;
    text-shadow: none !important;
}

.mes .tokenCounterDisplay {
    top: 17.2%;    /* 距离顶部的位置 */
    left: 26.5%;  /* 距离右边 的位置 */
}

.mes .mes_timer {
    top: 26.2%;    /* 距离顶部的位置 */
    left: 26.5%;  /* 距离右边的位置 */
}

.mes .mesIDDisplay{
    top: 11.2%;    /* 距离顶部的位置 */
    left: 26%;  /* 距离右边的位置 */
    letter-spacing: 0.15em;
    text-indent: -1.35em;         /* 把 # 推到左邊隱藏區 */
    padding-left: 0.8em;         /* 再把數字拉回來 */
    display: inline-block;       /* 確保 indent 生效 */
    overflow: hidden;            /* 可選：隱藏溢出部分 */
    font-size: 1.7vh;
    color: var(--darkword-color) !important;
    opacity: 1;
    font-family:"BoutiqueBitmap9x9";
}



/* =========================================
   🥚 角色名称
   ========================================= */
.mes .name_text {
    display: block !important; /* 确保它显示出来 */
    position: absolute !important; 
    margin-top: -60%;    
    left: 53%;  
    z-index: 60 !important;
    color: var(--title-color) !important; 
    font-weight: bold; 
    pointer-events: none; /* 让鼠标穿透名字，防止挡住点击 */
    font-size: 2vh;
    letter-spacing: 0.13em;
	line-height: 1.2em;
    font-family: "BoutiqueBitmap9x9";
}



/* =========================================
   🥚 菜单
   ========================================= */
/* 讓 .mes_buttons 溢出 .mes 容器邊界 */
.mes {
    overflow: visible !important;          /* 關鍵：允許子元素溢出 */
    position: relative !important;         /* 確保定位基準 */
}
.mes_buttons {
    position: absolute !important;         /* 改成 absolute 脫離正常流，自由定位 */
    margin-top: -4.3% !important;             
    right: 6% !important;
    width: auto !important;                /* 寬度自適應內容 */
    max-width: 90% !important;             /* 防止太寬擠爆 */
    padding: 8px 8px !important;
    z-index: 70 !important;                /* 確保在相框之上 */
    transition: all 0.3s ease !important;
	font-size: 1.9vh;
	align-items: center !important;
    justify-content: center !important;
    gap: 4px !important;
    padding: 10px 10px !important;
	display: flex !important;
	clip-path: none !important;
	overflow: visible !important;
	color: #dbb37f !important;
}
.mes_buttons > .extraMesButtonsHint,
.mes_buttons > .favorite-toggle-icon,
.mes_buttons > .st-screenshot-button,
.mes_buttons > .mes_edit {
    width: 35px !important;
    height: 33px !important;
    min-width: 20px !important;
    padding: 0 !important;
    margin: 0 !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;/* 獨立背景與明顯邊框 */
    transition: all 0.25s ease !important;
    cursor: pointer !important;
    position: relative !important;
    z-index: 71 !important;                 /* 確保單按鈕也高於相框 */
    opacity: 1 !important;
    visibility: visible !important;
	background: var(--woodboard-color)!important;                   
    border-radius: 0px 0px 4px 4px;            
	border: 5px double;
	border-color: #dbb37f!important;
    border-top: none !important;
    padding: 28px;                           /* 多留空间给内边线 */
}				

.mes_buttons > .extraMesButtons {
    position: absolute !important;
    right: 92% !important;                 /* 紧贴三个点左侧 */
    top: 50% !important;
    transform: translateY(-50%) !important;
    margin-right: 8px !important;           /* 与三个点按钮的间距，避免完全贴死 */
    flex-direction: row !important;
    gap: 4px !important;
    z-index: 81 !important;
    pointer-events: auto !important;
    white-space: nowrap !important;  
    /* 额外保险：防止自身裁剪 */
    overflow: visible !important;
}


/* =========================================
   🥚 文本 
   ========================================= */
.mes_text {
    text-align: justify;
    padding: 5px 18px 35px 9px; /* 内边距 */
    border-radius: 5px;
	text-shadow: none !important;
	letter-spacing: 1.1px;
}

/* 方法一：隐藏消息文本开头的所有br标签 by P1222*/
.mes_text br:first-child,
.mes_text br:nth-child(2),
.mes_text br:nth-child(3) {
    display: none !important;
}

/* 对话 */
.mes_text q {
	text-shadow: none !important;
	opacity:1;
}

/* 斜体 */
em {
    color: var(--emword) !important;
	text-shadow: none !important;
    border: 1.5px dashed var(--emword);
    border-radius: 6px;
    padding: 3px 4px 4px 4px;
    margin: 0 2px;
	opacity:1;
}

/* 代码块 */
body code {
    background: #504e76 !important;
    color: #fff;
    border: none;
    border-radius: 4px;
	padding: 0px 5px 1px 5px;
	font-size: 1.75vh;
}

/* `code` */
.mes pre code {
    margin-left:2.5%;
    background: #FBF8F0 !important;
	width:95%;
    border-radius: 12px;                
    border: 2px solid var(--darkword-color);              
    box-shadow:
        inset 0 -3px 0 0 #fcdd9d,          /* 底部黄色线（12px 高，可调） */
        inset -3px 0 0 0 #fcdd9d;          /* 右边黄色线（12px 宽，可调） */ 
    padding: 15px 20px 15px 15px;                         
    box-sizing: border-box;
    color: #504e76 !important;
	font-size: 1.5vh;
    font-family: "Fusion Pixel 12px M latin";
}

/* 代碼內文顏色 */
.hljs-attribute, .hljs-function .hljs-title, .hljs-section, 
.hljs-title.function_, .ruby .hljs-property, .hljs-attr, 
.hljs-link, .hljs-literal, .hljs-number, .hljs-symbol, 
.hljs-variable.constant_  {
    color: var(--darkword-color) !important;
}

.hljs-comment {
    color: #91CADF !important;
	font-size: 1.2vh;
}

.hljs-selector-class {
    color: #fc6d24 !important;
}

.hljs-meta, .hljs-meta .hljs-keyword, .hljs-meta .hljs-string {
    color: #1EBA4D !important;
}



/* =========================================
   🥚 思維鏈
   ========================================= */

/* 隱藏原標題文字 */
.mes_reasoning_header_title,
.mes_reasoning_header span[data-i18n="Thought for some time"] {
    display: none !important;
}

/* 隱藏原本的箭頭（你已經有這段，可保留） */
.mes_reasoning_arrow {
    display: none !important;
}

.mes_reasoning_header {
    position: absolute !important;
    margin-top: -15% !important;
    left: 13% !important;
    width: 23% !important;
    aspect-ratio: 5.1 / 2 !important;         /* ← 關鍵！讓 header 本身等比 */
    height: auto !important;                /* 高度自動依比例 */
    background-image: url("https://files.catbox.moe/rudq6i.png") !important;
    background-size: cover !important;
    background-position: center !important;
    background-color: transparent;
    pointer-events: auto !important;
    cursor: pointer !important;
}


/* =========================================
   🥚 topbar by 拼好碼
   ========================================= */
/* 导航栏背景 */
#top-bar {
    background-position: center;
    opacity:0;
    box-shadow: none;
}

/* 隐藏原有图标 */
#top-settings-holder .drawer-icon::before {
    content: '' !important;
    visibility: hidden; 
}
#top-settings-holder .drawer {
    flex: 1; 
}
#top-settings-holder .drawer-icon {
    display: block; 
    margin: 0 auto;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.3s ease-in-out;
    width: 25px; /* 图标宽度 */
    height: 25px; /* 图标高度 */
    opacity: 1 !important;
}

/* 图标替换 */
.drawer-icon.fa-sliders {
   background-image: url('https://files.catbox.moe/cz9da8.png'); /* AI响应配置 */
}
.drawer-icon.fa-plug {
   background-image: url('https://files.catbox.moe/zyy88i.png'); /* API连接 */
}
.drawer-icon.fa-font {
   background-image: url('https://files.catbox.moe/cz9da8.png'); /* AI回复格式化 */
}
.drawer-icon.fa-book-atlas {
   background-image: url('https://files.catbox.moe/zyy88i.png'); /* 世界信息 */
}
.drawer-icon.fa-user {
   background-image: url('https://files.catbox.moe/cz9da8.png'); /* 用户设置 */
}
.drawer-icon.fa-image {
   background-image: url('https://files.catbox.moe/zyy88i.png'); /* 背景图 */
}
.drawer-icon.fa-cubes {
   background-image: url('https://files.catbox.moe/cz9da8.png'); /* 扩展 */
}
.drawer-icon.fa-bars-progress {
   background-image: url('https://files.catbox.moe/zyy88i.png'); /* 记忆表格 */
}
.drawer-icon.fa-face-smile {
   background-image: url('https://files.catbox.moe/cz9da8.png'); /* 用户角色管理 */
}
.drawer-icon.fa-address-card {
   background-image: url('https://files.catbox.moe/zyy88i.png'); /* 角色卡 */
}
/* （可选）展开状态图标 */
#top-settings-holder .drawer .drawer-icon.openIcon {
    transform: scale(1.2); 
}



/* =========================================
   🥚 正则防误触&全显 （fr. 清酒）
   ========================================= */
#saved_regex_scripts, 
#saved_scoped_scripts {
  padding-right: 45px; 
}

.regex_script_name.flexGrow.overflow-hidden {
  overflow: visible;
  white-space: normal;
}

.regex-script-label.flex-container {
  align-items: center;
}



/* =========================================
   🥚 header / 標題 / 抽屜切換
   ========================================= */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader, 
.inline-drawer-header,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    border: none;
    background-image: none;
    background: var(--woodboard-color);           /* 主背景色 */
    color: var(--darkword-color);                /* 文字顏色（深棕金） */
    font-family: 'BoutiqueBitmap9x9', 'ChillBitmap 7px', monospace;
    font-weight: bold;
    padding: 7px 8px 3px 9px;
    border-radius: 8px;
    /* 立體邊框：外亮內暗 */
    border-top: 3px solid var(--woodlight);
    border-left: 3px solid var(--woodlight);
    border-bottom: 3px solid var(--woodshadow);
    border-right: 3px solid var(--woodshadow);
    transition: all 0.2s ease;
	line-height: 1.4;
}


/* =========================================
   🥚 預設面板
   ========================================= */
#completion_prompt_manager #completion_prompt_manager_list {
    background: none !important;
    border: none !important;
}

#left-nav-panel {
    border: none !important;
}

/* ====== Prompt 條目文字（排除 icon） ====== */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span:not(.fa):not([class*="fa-"]):not([class*="icon"]),
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt a:not(.fa):not([class*="fa-"]):not([class*="icon"]) {
    font-family: 'ChillBitmap 7px', monospace !important;
    color: var(--darkword-color);
    transition: color 0.3s ease !important;
}

/* 禁用狀態 */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
    background: var(--woodboard-color);
    opacity: 0.8 !important;
    border-radius: 8px;
    padding: 3px 8px 0px 8px;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled span:not(.fa):not([class*="fa-"]):not([class*="icon"]),
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled a:not(.fa):not([class*="fa-"]):not([class*="icon"]) {
    color: #907449 !important;
    font-weight: normal !important;
}

/* ====== Font Awesome 圖標（全局）====== */
.fa,
[class^="fa-"],
[class*=" fa-"],
[class*="icon"] {
    font-family: "Font Awesome 6 Free", "Font Awesome 6 Brands", "Font Awesome 5 Free", sans-serif !important;
    font-weight: 900 !important;
    color: rgb(99, 77, 53) !important;
    text-shadow: none !important;
    box-shadow: none !important;
}

/* Prompt Manager 內特定圖標/元件去陰影 */
#completion_prompt_manager .fa,
#completion_prompt_manager .toggle,
#completion_prompt_manager [class*="toggle"],
#completion_prompt_manager .slider,
#completion_prompt_manager .fa-link,
#completion_prompt_manager [class*="chain"],
#completion_prompt_manager .fa-pencil,
#completion_prompt_manager .fa-edit {
    text-shadow: none !important;
    box-shadow: none !important;
    filter: none !important;
}

#completion_prompt_manager .toggle::before,
#completion_prompt_manager .toggle::after,
#completion_prompt_manager .slider {
    background: rgb(99, 77, 53) !important;
    box-shadow: none !important;
}

/* ====== 表頭（名稱 & 代幣）====== */
.completion_prompt_manager_header,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_list_head span[data-i18n="Name"],
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_list_head span:first-child,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_list_head span.prompt_manager_prompt_tokens,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_list_head span[data-i18n="Tokens;prompt_manager_tokens"] {
    font-family: 'BoutiqueBitmap9x9', monospace !important;
    font-size: 14px !important;
    font-weight: bold !important;
    color: var(--darkword-color) !important;
    letter-spacing: 0.5px !important;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_list_head span.prompt_manager_prompt_tokens {
    text-align: right !important;
}

/* ====== 進階標題去陰影 ====== */
.completion_prompt_manager_header_advanced,
.completion_prompt_manager_header_advanced * {
    text-shadow: none !important;
    filter: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

/* ====== 「角色名稱行為」、「繼續後綴」不換行 ====== */
.flex-container.alignItemsCenter small {
    flex-basis: auto !important;
    white-space: nowrap !important;
}

#character_names_display {
    white-space: nowrap !important;
}

/* ====== inline-drawer chevron 圖示大小 ====== */
.inline-drawer-icon.fa-circle-chevron-down,
.inline-drawer-icon.fa-solid.fa-circle-chevron-down,
.inline-drawer-icon.fa-circle-chevron-up,
.inline-drawer-icon.fa-solid.fa-circle-chevron-up {
    font-size: 1.2em !important;
    line-height: 1 !important;
    vertical-align: middle !important;
}

/* ====== 隱藏分隔線 ====== */
.completion_prompt_manager_list_separator,
.completion_prompt_manager_list_separator hr {
    display: none !important;
}


/* 完全禁用所有列出的元素的 hover 效果 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover,
#user-settings-block h4:hover,
.standoutHeader:hover,
.inline-drawer-header:hover,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled):hover,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover,
#completion_prompt_manager #completion_prompt_manager_list li:hover {
    /* 強制保持原始樣式，不允許任何變化 */
    filter: none !important;                         /* 移除任何亮度/模糊濾鏡 */
    outline: none !important;                        /* 移除 focus/hover outline */
    opacity: 1 !important;                           /* 不變淡或變亮 */
    transition: none !important;                     /* 關閉所有過渡動畫，避免閃爍 */
    cursor: pointer !important;                      /* 改成文字游標（可選，如果你不想要 pointer） */
}

/* 額外覆蓋常見的 interactable/highlight 類別（如果預設樣式用了這些） */
.interactable:hover,
.hover-highlight:hover,
[role="button"]:hover,
[tabindex="0"]:hover,
.inline-drawer-toggle:hover {
    box-shadow: inherit !important;
    filter: none !important;
    outline: none !important;
    transition: none !important;
}

/* 強制鎖定所有指定元素的 hover 狀態：完全不變、不亮、不加陰影 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover,
#user-settings-block h4:hover,
.standoutHeader:hover,
.inline-drawer-header:hover {
    background: var(--woodboard-color) !important;                  
    background-image: none !important;
    border: 3px solid var(--woodshadow) !important;            
