    border-radius: 0 !important;
}

/* 3. 悬停交互修复 (防止悬停时变回橙色圆圈) */
input[type="range"]:hover::-webkit-slider-thumb,
input[type="range"]:active::-webkit-slider-thumb {
    background-color: transparent !important; /* 保持透明 */
    transform: scale(1.2); /* 仅放大 */
}
